/**
 * @suppress
 */
public object FfiConverterTypeLaneSession: FfiConverter<LaneSession, Pointer> {

    override fun lower(value: LaneSession): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): LaneSession {
        return LaneSession(value)
    }

    override fun read(buf: ByteBuffer): LaneSession {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: LaneSession) = 8UL

    override fun write(value: LaneSession, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



