sealed class LaneException: kotlin.Exception() {
    
    class Io(
        
        val `message`: kotlin.String
        ) : LaneException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class Protocol(
        
        val `message`: kotlin.String
        ) : LaneException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class AuthFailed(
        ) : LaneException() {
        override val message
            get() = ""
    }
    
    class Closed(
        ) : LaneException() {
        override val message
            get() = ""
    }
    
    class Timeout(
        
        val `message`: kotlin.String
        ) : LaneException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class Media(
        
        val `message`: kotlin.String
        ) : LaneException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class E2ee(
        
        val `message`: kotlin.String
        ) : LaneException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class InvalidArgument(
        
        val `message`: kotlin.String
        ) : LaneException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class NotConnected(
        ) : LaneException() {
        override val message
            get() = ""
    }
    
    class Internal(
        
        val `message`: kotlin.String
        ) : LaneException() {
        override val message
            get() = "message=${ `message` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LaneException> {
        override fun lift(error_buf: RustBuffer.ByValue): LaneException = FfiConverterTypeLaneError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLaneError : FfiConverterRustBuffer<LaneException> {
    override fun read(buf: ByteBuffer): LaneException {
        

        return when(buf.getInt()) {
            1 -> LaneException.Io(
                FfiConverterString.read(buf),
                )
            2 -> LaneException.Protocol(
                FfiConverterString.read(buf),
                )
            3 -> LaneException.AuthFailed()
            4 -> LaneException.Closed()
            5 -> LaneException.Timeout(
                FfiConverterString.read(buf),
                )
            6 -> LaneException.Media(
                FfiConverterString.read(buf),
                )
            7 -> LaneException.E2ee(
                FfiConverterString.read(buf),
                )
            8 -> LaneException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            9 -> LaneException.NotConnected()
            10 -> LaneException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LaneException): ULong {
        return when(value) {
            is LaneException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is LaneException.Protocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is LaneException.AuthFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LaneException.Closed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LaneException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is LaneException.Media -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is LaneException.E2ee -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is LaneException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is LaneException.NotConnected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LaneException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: LaneException, buf: ByteBuffer) {
        when(value) {
            is LaneException.Io -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is LaneException.Protocol -> {
                buf.putInt(2)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is LaneException.AuthFailed -> {
                buf.putInt(3)
                Unit
            }
            is LaneException.Closed -> {
                buf.putInt(4)
                Unit
            }
            is LaneException.Timeout -> {
                buf.putInt(5)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is LaneException.Media -> {
                buf.putInt(6)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is LaneException.E2ee -> {
                buf.putInt(7)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is LaneException.InvalidArgument -> {
                buf.putInt(8)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is LaneException.NotConnected -> {
                buf.putInt(9)
                Unit
            }
            is LaneException.Internal -> {
                buf.putInt(10)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceString: FfiConverterRustBuffer<List<kotlin.String>> {
    override fun read(buf: ByteBuffer): List<kotlin.String> {
        val len = buf.getInt()
        return List<kotlin.String>(len) {
            FfiConverterString.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.String>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterString.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.String>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterString.write(it, buf)
        }
    }
}
